"use client";
// @zeus-internal
import { MeshGradient } from "@paper-design/shaders-react";
import { Smartphone } from "lucide-react";
import { AnimatePresence, animate, motion, useInView, useMotionValue, useReducedMotion, useSpring } from "motion/react";
import { type FocusEvent, type PointerEvent, useEffect, useRef, useState } from "react";
import { ArtemisButtonLink } from "../../../foundations/button";
import { artemisButtonClasses } from "../../../foundations/button-classes";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import { avatar, FEATURES, type Feature } from "./01-phone-tour/data";
import { FeatureTabs } from "./01-phone-tour/feature-tabs";
import { PhoneScreen } from "./01-phone-tour/screens";
const ADVANCE_MS = 5000;
const TILT_DEG = 14;
const TILT_SPRING = { stiffness: 200, damping: 15, mass: 0.3 };
const MESH_COLORS = ["#f3d9c2", "#9fd6c9", "#f0c08f", "#b9d3ea"];
const SCREEN_VARIANTS = {
    enter: (dir: number) => ({ opacity: 0, filter: "blur(6px)", x: `${24 * dir}%` }),
    center: { opacity: 1, filter: "blur(0px)", x: "0%" },
    exit: (dir: number) => ({ opacity: 0, filter: "blur(6px)", x: `${-24 * dir}%` }),
};
const FEATURE_BUTTON = artemisButtonClasses({
    variant: "ghost",
    size: "none",
    className: "art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:block art:w-full art:p-5 art:text-left art:focus-visible:ring-0 art:focus-visible:ring-offset-0",
});
const PROGRESS_FILL = "art:block art:h-full art:origin-left art:bg-foreground";
function ProgressFill() {
    const scaleX = useMotionValue(0);
    useEffect(() => {
        const controls = animate(scaleX, 1, { duration: ADVANCE_MS / 1000, ease: "linear" });
        return () => controls.stop();
    }, [scaleX]);
    return <motion.span className={PROGRESS_FILL} style={{ scaleX }}/>;
}
function FeatureItem({ feature, active, paused, onSelect, }: {
    feature: Feature;
    active: boolean;
    paused: boolean;
    onSelect: () => void;
}) {
    const Icon = feature.icon;
    return (<li className={artemisCx("art:rounded-2xl art:border art:transition-colors art:duration-300 art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-foreground", active ? "art:border-border" : "art:border-transparent")}>
      <button type="button" className={FEATURE_BUTTON} aria-pressed={active} onClick={onSelect}>
        <span className="art:flex art:items-center art:gap-3">
          <span className={artemisCx("art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:transition-colors art:duration-300", active ? "art:text-foreground" : "art:text-muted-foreground")}>
            <Icon className="art:size-4" aria-hidden="true"/>
          </span>
          <span className={artemisCx("art:font-medium art:text-xl art:transition-colors art:duration-300", active ? "art:text-foreground" : "art:text-muted-foreground")}>
            {feature.title}
