        </span>
      </button>
    </li>);
}
export default function AppShowcasePhoneTour() {
    const reduce = useReducedMotion();
    const [active, setActive] = useState(0);
    const [direction, setDirection] = useState(1);
    const [interacting, setInteracting] = useState(false);
    const sectionRef = useRef<HTMLElement>(null);
    const inView = useInView(sectionRef, { margin: "-20% 0px -20% 0px" });
    const paused = reduce || interacting || !inView;
    const tiltX = useSpring(0, TILT_SPRING);
    const tiltY = useSpring(0, TILT_SPRING);
    const feature = FEATURES[active];
    useEffect(() => {
        if (paused)
            return;
        const id = window.setTimeout(() => {
            setDirection(1);
            setActive((index) => (index + 1) % FEATURES.length);
        }, ADVANCE_MS);
        return () => window.clearTimeout(id);
    }, [active, paused]);
    const select = (index: number) => {
        if (index === active)
            return;
        setDirection(index > active ? 1 : -1);
        setActive(index);
    };
    const onFocus = (event: FocusEvent<HTMLDivElement>) => {
        if (event.target instanceof HTMLElement && event.target.matches(":focus-visible"))
            setInteracting(true);
    };
    const onBlur = (event: FocusEvent<HTMLDivElement>) => {
        const next = event.relatedTarget;
        if (!(next instanceof Node) || !event.currentTarget.contains(next))
            setInteracting(false);
    };
    const onStageMove = (event: PointerEvent<HTMLDivElement>) => {
        if (reduce)
            return;
        const rect = event.currentTarget.getBoundingClientRect();
        const px = (event.clientX - rect.left) / rect.width - 0.5;
        const py = (event.clientY - rect.top) / rect.height - 0.5;
        tiltX.set(-py * TILT_DEG);
        tiltY.set(px * TILT_DEG);
    };
    const onStageLeave = () => {
        tiltX.set(0);
        tiltY.set(0);
    };
    const list = (indexes: readonly number[]) => (<ul className="art:hidden art:space-y-2 art:@min-[1024px]/artemis:block">
      {indexes.map((index) => (<FeatureItem key={FEATURES[index].id} feature={FEATURES[index]} active={index === active} paused={paused} onSelect={() => select(index)}/>))}
    </ul>);
    return (<section ref={sectionRef} aria-labelledby="app-showcase-title" className="art:w-full art:overflow-hidden art:font-sans art:text-foreground">
