              <Smartphone className="art:size-4" aria-hidden="true"/>
              Download for iPhone
            </ArtemisButtonLink>
            <ArtemisButtonLink href="#" variant="tertiary" className="art:h-9">
              Get it on Android
            </ArtemisButtonLink>
          </div>
        </div>
        <div className="art:mt-12 art:grid art:items-center art:gap-8 art:@min-[1024px]/artemis:mt-16 art:@min-[1024px]/artemis:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] art:@min-[1024px]/artemis:gap-10" onPointerEnter={() => setInteracting(true)} onPointerLeave={() => setInteracting(false)} onFocus={onFocus} onBlur={onBlur}>
          {list([0, 1])}
          <div className="art:@min-[1024px]/artemis:hidden">
            <div>
              <FeatureTabs items={FEATURES.map((f) => ({ value: f.id, label: f.tab }))} value={feature.id} onValueChange={(value) => select(FEATURES.findIndex((f) => f.id === value))}/>
            </div>
            <AnimatePresence mode="wait" initial={false}>
              <motion.p key={feature.id} className="art:mt-4 art:min-h-12 art:text-center art:text-muted-foreground art:text-sm art:leading-6" aria-live="polite" initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={reduce ? { opacity: 1, y: 0 } : { opacity: 0, y: -4 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL}>
                {feature.body}
              </motion.p>
            </AnimatePresence>
          </div>
          <div className="art:relative art:mx-auto art:grid art:w-full art:max-w-md art:place-items-center art:overflow-hidden art:rounded-4xl art:border art:border-border art:px-6 art:py-10 art:@min-[640px]/artemis:px-12 art:@min-[1024px]/artemis:w-md" style={{ perspective: 1200 }} onPointerMove={onStageMove} onPointerLeave={onStageLeave}>
            <div aria-hidden="true" className="art:absolute art:inset-0">
              <MeshGradient className="art:h-full art:w-full" colors={MESH_COLORS} distortion={0.55} swirl={0.3} speed={0.14}/>
              <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/30"/>
            </div>
            <motion.div className="art:relative" style={{ rotateX: tiltX, rotateY: tiltY }}>
              <div role="img" aria-label={`App screen: ${feature.title}`} className="art:relative art:w-72 art:rounded-4xl art:border art:border-border art:bg-background art:p-2">
                <div className="art:relative art:h-[32rem] art:overflow-hidden art:rounded-3xl art:border art:border-border art:bg-background">
                  <div className="art:flex art:items-center art:justify-between art:px-5 art:pt-3 art:pb-2 art:font-medium art:text-xs">
                    <span className="art:tabular-nums">9:41</span>
                    <span className="art:h-5 art:w-20 art:rounded-full art:bg-foreground"/>
                    <span className="art:text-muted-foreground">5G</span>
                  </div>
                  <AnimatePresence initial={false} custom={direction}>
                    <motion.div key={feature.id} custom={direction} variants={reduce ? undefined : SCREEN_VARIANTS} initial={reduce ? false : "enter"} animate={reduce ? undefined : "center"} exit={reduce ? { opacity: 0 } : "exit"} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT} className="art:absolute art:inset-x-0 art:top-10 art:bottom-0 art:px-4 art:pb-4">
                      <PhoneScreen id={feature.id}/>
                    </motion.div>
                  </AnimatePresence>
                </div>
              </div>
            </motion.div>
            <div className="art:pointer-events-none art:absolute art:inset-x-4 art:bottom-5 art:flex art:justify-center art:@min-[640px]/artemis:inset-x-6">
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.div key={feature.id} className="art:flex art:items-center art:gap-2.5 art:rounded-full art:border art:border-border art:bg-background/85 art:py-1.5 art:pr-4 art:pl-1.5 art:text-sm art:backdrop-blur-md" initial={reduce ? false : { opacity: 0, y: 14, scale: 0.92, filter: "blur(4px)" }} animate={{ opacity: 1, y: 0, scale: 1, filter: "blur(0px)" }} exit={reduce ? { opacity: 1, y: 0, scale: 1 } : { opacity: 0, y: -8, scale: 0.96, transition: { duration: 0.15, ease: "easeOut" } }} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 0.35 }}>
                  <img src={avatar(feature.activity.avatar)} alt="" width={28} height={28} className="art:size-7 art:rounded-full art:object-cover"/>
                  <span className="art:whitespace-nowrap">{feature.activity.text}</span>
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
          {list([2, 3])}
        </div>
      </div>
    </section>);
}

